using System; using System.Threading.Tasks; using System.Web.Http; using EnterpriseInvoiceSystem.DTOs; using EnterpriseInvoiceSystem.Services;
namespace EnterpriseInvoiceSystem.Controllers { [RoutePrefix("api/invoices")] public class InvoicesController:ApiController { readonly InvoiceService service=new InvoiceService(); [HttpGet,Route("")] public async Task<IHttpActionResult> All(){return Ok(await service.GetAllAsync());} [HttpGet,Route("{id:int}")] public async Task<IHttpActionResult> Get(int id){var x=await service.GetAsync(id);return x==null?(IHttpActionResult)NotFound():Ok(x);} [HttpPost,Route("")] public async Task<IHttpActionResult> Post(CreateInvoiceRequest r){if(!ModelState.IsValid)return BadRequest(ModelState);try{var x=await service.CreateAsync(r);return CreatedAtRoute("DefaultApi",new{id=x.Id},x);}catch(ConflictException ex){return Content(System.Net.HttpStatusCode.Conflict,new{message="Invoice creation failed.",detail=ex.Message});}catch(BusinessException ex){return Content(System.Net.HttpStatusCode.BadRequest,new{message="Invoice creation failed.",detail=ex.Message});}catch(Exception){return Content(System.Net.HttpStatusCode.InternalServerError,new{message="Invoice creation failed.",detail="An unexpected database error occurred."});}} } }
